#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin>>n;
    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>ksz[i]; raw[i].resize(ksz[i]);
        for(int j=0;j<ksz[i];j++) cin>>raw[i][j].first>>raw[i][j].second;
        totalCells+=ksz[i];
    }

    // Transform: first flip (negate x if f=1), then rotate CCW r times
    // CCW rotation: (x,y) -> (-y,x)
    auto transform=[](vector<pair<int,int>> cells, int r, int f)->vector<pair<int,int>>{
        for(auto&[x,y]:cells) if(f) x=-x;
        for(int rr=0;rr<r;rr++) for(auto&[x,y]:cells){int nx=-y,ny=x;x=nx;y=ny;}
        int mx=INT_MAX,my=INT_MAX;
        for(auto[x,y]:cells){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:cells){x-=mx;y-=my;}
        sort(cells.begin(),cells.end());
        return cells;
    };

    struct Orient{vector<pair<int,int>> cells;int w,h,r,f;};
    vector<vector<Orient>> allO(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            auto c=transform(raw[i],r,f);
            if(seen.insert(c).second){
                int Mx=0,My=0;
                for(auto[x,y]:c){Mx=max(Mx,x);My=max(My,y);}
                allO[i].push_back({c,Mx+1,My+1,r,f});
            }
        }
    }

    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return ksz[a]>ksz[b];});

    int sq=max(1,(int)ceil(sqrt((double)totalCells)));
    long long bestArea=LLONG_MAX;
    int bestW=0,bestH=0;
    vector<int> bx(n),by(n),br(n),bf(n);
    auto ST=chrono::steady_clock::now();
    auto ms=[&](){return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-ST).count();};

    int maxDim=totalCells+10;
    for(int W=max(1,sq-15);W<=min(maxDim,totalCells)&&ms()<8500;W++){
        vector<int> ch(W+200,0);
        vector<vector<bool>> grid(W+200,vector<bool>(maxDim,false));
        vector<int> px(n),py(n),pr(n),pf(n);
        bool ok=true; int mxH=0;
        for(int idx=0;idx<n;idx++){
            int i=ord[idx]; int bs=INT_MAX; int bxx=-1,byy=-1,boi=-1;
            for(int oi=0;oi<(int)allO[i].size();oi++){
                auto&o=allO[i][oi];
                if(o.w>W) continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0;
                    for(auto[cx,cy]:o.cells) my=max(my,ch[x+cx]-cy);
                    if(my<0)my=0;
                    for(int y=my;;y++){
                        int nh=max(mxH,y+o.h);
                        if(nh>=bs) break;
                        bool good=true;
                        for(auto[cx,cy]:o.cells) if(grid[x+cx][y+cy]){good=false;break;}
                        if(good){bs=nh;bxx=x;byy=y;boi=oi;break;}
                    }
                }
            }
            if(bxx<0){ok=false;break;}
            auto&o=allO[i][boi];
            px[i]=bxx;py[i]=byy;pr[i]=o.r;pf[i]=o.f;
            for(auto[cx,cy]:o.cells){grid[bxx+cx][byy+cy]=true;ch[bxx+cx]=max(ch[bxx+cx],byy+cy+1);mxH=max(mxH,byy+cy+1);}
        }
        if(!ok) continue;
        long long a=(long long)W*mxH;
        if(a<bestArea){bestArea=a;bestW=W;bestH=mxH;bx=px;by=py;br=pr;bf=pf;}
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
